Method.Implementation:

do ##super()
#DIM status AS %Status
set status = $$$OK		

try{
	// set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrTuxStringAddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)		
	set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrTuxStringAddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))

	set status = ..CheckObject()

}catch err{
   $$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    	 
   set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)

}	
Quit status

 #DIM status AS %Status
 set status = $$$OK	 

 try{
	 if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("IHC.ITF.ITFCOMMON.Operation.CdrHl7AddUpdateOperation", "Failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
			return status
		}
 	}

	 		$$$TRACE(" Calling MMI Merge .."_pRequest.hl7Msg.RawContent) 				 				 				 		
	 		set pResponse=##class(Ens.StringResponse).%New()		 		
	 		set result = ..objCdrTuxService.callAddUpdate(pRequest.hl7Msg.RawContent)	
	 		Set pResponse.StringValue = result
	 		Set respData = pResponse.StringValue		 		
	 		$$$TRACE(" Call after the Merge .."_respData)		 				 		

 } catch err {	
	    Set status = ..ExceptionHandler(err, "OnMessage")
 }	    

 $$$TRACE("OnMessage status: " _ status)	
 return status
